<?php
declare(strict_types=1);
require_once __DIR__.'/WorkspaceUI.php';
require_once __DIR__.'/OrganizationBranding.php';

/** One focused editor surface over the existing Playbill actions. */
final class PlaybillStudio
{
    public static function render(PDO $db,string $base,array $user,?array $production,?array $pb):never
    {
        $tabs=['overview'=>'Overview','cover'=>'Cover & Design','company'=>'Cast & Crew','bios'=>'Biographies & Headshots','content'=>'Program Content','sponsors'=>'Sponsors & Advertising','publish'=>'Preview & Publish'];
        $tab=(string)($_GET['tab']??'overview');if(!isset($tabs[$tab]))$tab='overview';
        $u=static fn(string $p):string=>$base.$p;$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
        $cast=$pb?PlaybillEnhancementService::playbillCastProfiles($db,(int)$pb['id']):[];$sponsors=$pb?PlaybillEnhancementService::sponsors($db,(int)$pb['id']):[];
        $sections=[];if($pb){$q=$db->prepare('SELECT * FROM playbill_sections WHERE playbill_id=? ORDER BY sort_order,id');$q->execute([(int)$pb['id']]);$sections=$q->fetchAll();}
        $closed=$production&&in_array($production['lifecycle_stage'],['completed','archived'],true);
        $locked=$closed||($pb&&($pb['public_enabled']||$pb['editorial_status']==='archived'));
        $url=$u('/admin/playbill?production='.(int)($production['id']??0));$preview=$url.'&preview=1';
        $public=$u('/playbill?slug='.rawurlencode((string)($pb['public_slug']??'')));
        $csrf='<input type="hidden" name="csrf_token" value="'.$e($_SESSION['playbill_csrf']).'"><input type="hidden" name="production_id" value="'.(int)($production['id']??0).'"><input type="hidden" name="playbill_id" value="'.(int)($pb['id']??0).'"><input type="hidden" name="studio_tab" value="'.$e($tab).'">';
        $flash=$_SESSION['playbill_flash']??$_SESSION['pb2_flash']??null;unset($_SESSION['playbill_flash'],$_SESSION['pb2_flash']);
        $pending=count(array_filter($cast,static fn(array $p):bool=>$p['visible']&&$p['approval_status']!=='approved'));
        header('Content-Type:text/html; charset=utf-8');header('Cache-Control: private, no-store');?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playbill Studio</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><?php WorkspaceUI::operationsStyles($base);?><link rel="stylesheet" href="<?=$u('/assets/css/playbill-studio.css?v=20261030-1')?>"><script defer src="<?=$u('/assets/js/playbill-studio.js?v=20261030-1')?>"></script></head><body class="app-body ux-workspace ux-operations"><a class="ux-skip" href="#studio-main">Skip to Studio</a><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/playbill',$base,$user);?><main class="unified-main" id="studio-main" tabindex="-1"><?php AppNavigation::renderHeader('Production','Playbill Studio',$base);?><div class="studio ops-page">
<?php if(!$production):?><h2>Choose a production to begin.</h2><a href="<?=$u('/production')?>">Open production workspace</a><?php else:?>
<header class="studio-heading"><div><p><?=$e($production['title'])?></p><h2><?=$e($pb['display_title']??'Create the program')?></h2></div><div class="studio-heading-actions"><span class="studio-status"><?=$pb?($pb['public_enabled']?'Public · ':'Private · ').$e(ucfirst($pb['editorial_status'])):'Not created'?></span><?php if($pb):?><a class="button secondary" href="<?=$e($preview)?>" target="_blank" rel="noopener">Preview saved program</a><?php endif;?></div></header>
<?php if($flash):?><div class="studio-notice" role="status"><?=$e($flash['message'])?></div><?php endif;?>
<?php if($locked):?><p class="studio-notice"><?=$closed?'Historical production: editorial changes are closed.':($pb['public_enabled']?'This edition is live. Unpublish before making changes; publish again after reviewing the saved draft.':'Archived program: this editorial record is read-only.')?></p><?php endif;?>
<nav class="studio-tabs" aria-label="Program editing stages"><?php foreach($tabs as $key=>$label):?><a href="<?=$e($url.'&tab='.$key)?>" <?=$key===$tab?'aria-current="page"':''?>><?=$e($label)?></a><?php endforeach;?></nav>
<p class="studio-save-state" data-save-state aria-live="polite">Showing saved content. Edits remain unsaved until you submit a form.</p>
<?php if($tab==='overview'):?>
<section class="studio-overview"><div><h3>Your program at a glance</h3><dl><div><dt>Company profiles</dt><dd><?=count($cast)?> · <?=count(array_filter($cast,static fn(array $p):bool=>(bool)$p['visible']))?> marked for inclusion</dd></div><div><dt>Consent</dt><dd><?=$pending?> visible profiles need review</dd></div><div><dt>Content</dt><dd><?=count(array_filter($sections,static fn(array $s):bool=>(bool)$s['active']))?> visible sections</dd></div><div><dt>Sponsors</dt><dd><?=count(array_filter($sponsors,static fn(array $s):bool=>(bool)$s['attachment_active']))?> placements</dd></div><div><dt>Cover</dt><dd><?=!empty($pb['artwork_stored_file_id'])?'Artwork saved':'Typography cover · no artwork uploaded'?></dd></div></dl><p>Start with the cover, review company consent, then preview and publish. Public production announcements do not publish this program.</p><a href="<?=$e($url.'&tab=cover')?>">Edit cover &amp; design →</a></div><?php if(!empty($pb['artwork_stored_file_id'])):?><img class="studio-cover-thumb" src="<?=$e($url.'&preview_asset=1&kind=artwork')?>" alt="Saved program cover"><?php endif;?></section>
<?php endif;?>
<?php if($tab==='cover'||!$pb):?><section class="studio-panel"><h3><?=$pb?'Cover details':'Create a Playbill'?></h3><form method="post" class="studio-form"><?=$csrf?><input type="hidden" name="action" value="save_playbill"><fieldset <?=$locked?'disabled':''?>><label>Program title<input name="display_title" maxlength="190" required value="<?=$e($pb['display_title']??$production['title'])?>"></label><label>Subtitle<input name="subtitle" maxlength="255" value="<?=$e($pb['subtitle']??$production['season'])?>"></label><label>Cover note<textarea name="cover_note" maxlength="500" rows="3"><?=$e($pb['cover_note']??'')?></textarea></label><label>Permanent public address<input name="public_slug" maxlength="190" required value="<?=$e($pb['public_slug']??'')?>" <?=!empty($pb['published_at'])?'readonly':''?>></label><details><summary>Program description &amp; audience links</summary><label>Short program description<textarea name="public_description" maxlength="500" rows="3"><?=$e($pb['public_description']??'')?></textarea></label><?php foreach(['website_url'=>'Theatre website','upcoming_url'=>'Upcoming productions URL','donate_url'=>'Support / donate URL'] as $key=>$label):?><label><?=$label?><input type="url" name="<?=$key?>" maxlength="1000" value="<?=$e($pb[$key]??'')?>"></label><?php endforeach;?></details><button class="button" type="submit">Save cover details</button></fieldset></form></section>
<?php if($pb):?><section class="studio-panel"><h3>Cover artwork &amp; presentation</h3><p>Uses the shared organization identity and publication typography. Cover images are contained rather than stretched.</p><form class="studio-form" method="post" enctype="multipart/form-data"><?=$csrf?><input type="hidden" name="action" value="artwork"><fieldset <?=$locked?'disabled':''?>><label>Upload cover image<input type="file" name="artwork" accept="image/jpeg,image/png,image/webp" required></label><button class="button" type="submit">Save artwork</button></fieldset></form><form class="studio-form" method="post"><?=$csrf?><input type="hidden" name="action" value="cover_display"><fieldset <?=$locked?'disabled':''?>><label>Cover layout<select name="cover_display"><option value="artwork_and_text" <?=($pb['cover_display']??'')==='artwork_and_text'?'selected':''?>>Artwork with title</option><option value="artwork_only" <?=($pb['cover_display']??'')==='artwork_only'?'selected':''?>>Complete artwork only</option></select></label><button class="button" type="submit">Save cover layout</button></fieldset></form></section><?php endif;?><?php endif;?>
<?php if($pb&&$tab==='company'):?><section class="studio-panel"><h3>Cast &amp; company</h3><p>Accepted cast members and eligible team members use their existing accounts. Manual participants stay linked to their original production credits; transferred entries are not duplicated.</p><div class="studio-company"><?php foreach($cast as $p):?><article><div><strong><?=$e($p['display_name'])?></strong><span><?=$e($p['role_title']?:'Credit not set')?> · <?=$e($p['identity_type'])?></span></div><span><?=$p['visible']?'Included':'Hidden'?> · <?=$e($p['approval_status'])?></span><a href="<?=$e($url.'&tab=bios#person-'.(int)$p['user_id'])?>">Edit profile</a></article><?php endforeach;?></div><a href="<?=$u('/production/casting')?>">Casting &amp; manual participant records →</a></section><section class="studio-panel"><h3>Reviewed Production Team credits</h3><p>Import approved public names and functions, without private notes or contact information.</p><?php $team=ProductionTeamPublicationService::candidates($db,(int)$production['id'],(int)$pb['id']);?><ul><?php foreach($team as $credit):?><li><?=$e($credit['name'])?> · <?=$e($credit['participation_role'])?></li><?php endforeach;?></ul><form method="post"><?=$csrf?><input type="hidden" name="team_fingerprint" value="<?=$e(ProductionTeamPublicationService::fingerprint($team))?>"><button class="button" name="action" value="import_team" <?=$locked?'disabled':''?>>Import reviewed team credits</button></form></section><?php endif;?>
<?php if($pb&&$tab==='bios'):?><section class="studio-panel"><h3>Biographies &amp; headshots</h3><p>These are Playbill-specific snapshots. Saving here never overwrites the shared performer profile. Changed public details require fresh consent; Students use first name and last initial publicly.</p><?php foreach($cast as $p):?><details class="studio-editor" id="person-<?=(int)$p['user_id']?>"><summary><span><strong><?=$e($p['display_name'])?></strong><small><?=$e($p['role_title'])?></small></span><span><?=$p['visible']?'Included':'Hidden'?> · <?=$e($p['approval_status'])?></span></summary><form method="post" enctype="multipart/form-data" class="studio-form"><?=$csrf?><input type="hidden" name="action" value="save_cast"><input type="hidden" name="user_id" value="<?=(int)$p['user_id']?>"><fieldset <?=$locked?'disabled':''?>><label>Editorial display name<input name="display_name" maxlength="190" required value="<?=$e($p['display_name'])?>"></label><label>Role or combined credits<input name="role_title" maxlength="190" value="<?=$e($p['role_title'])?>"></label><label>Biography<textarea name="biography" maxlength="3000" rows="5"><?=$e($p['biography'])?></textarea></label><?php if($p['identity_type']==='registered'):?><label>Headshot override<input type="file" name="headshot" accept="image/jpeg,image/png,image/webp"></label><label>Photographer credit<input name="photographer_credit" maxlength="190" value="<?=$e($p['photographer_credit'])?>"></label><?php if($p['master_bio']||$p['master_headshot_id']):?><details><summary>Reusable performer profile</summary><p><?=$e($p['master_bio']?:'A shared headshot is available.')?></p><label class="studio-check"><input type="checkbox" name="use_shared_profile" value="1"> Replace this program's biography and headshot with the shared profile when saving</label></details><?php endif;?><?php else:?><p>Headshot and consent originate in the existing manual participant record. Biography and credit overrides apply to this program only.</p><?php if(AccessPolicy::canManageProduction($user)):$consent=$db->prepare('SELECT approve_public_name,approve_public_biography,approve_public_headshot FROM playbill_manual_profiles WHERE playbill_id=? AND manual_credit_id=?');$consent->execute([(int)$pb['id'],abs((int)$p['user_id'])]);$review=$consent->fetch();?><details><summary>Review manual publication consent</summary><p>Confirm permission for the displayed program details. The original manual record must also retain its public approvals.</p><label class="studio-check"><input type="checkbox" name="review_manual_consent" value="1"> I reviewed this participant's permission</label><?php foreach(['approve_public_name'=>'Public name','approve_public_biography'=>'Biography','approve_public_headshot'=>'Headshot'] as $key=>$label):?><label class="studio-check"><input type="checkbox" name="<?=$key?>" value="1" <?=$review[$key]?'checked':''?>> <?=$label?></label><?php endforeach;?></details><?php endif;?><?php endif;?><label>Display order<input type="number" name="display_order" value="<?=(int)$p['display_order']?>"></label><label class="studio-check"><input type="checkbox" name="visible" value="1" <?=$p['visible']?'checked':''?>> Include in program (consent still required)</label><button class="button" type="submit">Save program profile</button></fieldset></form><?php if($p['identity_type']==='registered'):?><p>Participant consent link: <a href="<?=$u('/playbill/consent?profile='.(int)$p['id'])?>">Review saved profile</a> (available only to the profile owner or the Student’s current parent/guardian).</p><?php endif;?><?php if((int)$p['user_id']===(int)$user['id']&&!$locked):?><form method="post"><?=$csrf?><button class="button secondary" name="action" value="approve_own_profile">Approve my saved public profile</button></form><?php endif;?></details><?php endforeach;?></section><?php endif;?>
<?php if($pb&&$tab==='content'):?><section class="studio-panel"><h3>Program content</h3><p>Order determines the reading sequence. Blank lines separate paragraphs; lines beginning with “- ” become lists.</p><?php foreach($sections as $section):if($section['section_type']==='production_team_snapshot')continue;?><details class="studio-editor"><summary><strong><?=$e($section['heading'])?></strong><span><?=$section['active']?'Visible':'Hidden'?> · order <?=(int)$section['sort_order']?></span></summary><?php self::sectionForm($csrf,$section,$locked,$e);?><form method="post"><?=$csrf?><input type="hidden" name="section_id" value="<?=(int)$section['id']?>"><button name="action" value="toggle_section" <?=$locked?'disabled':''?>><?=$section['active']?'Hide section':'Show section'?></button></form></details><?php endforeach;?><details class="studio-editor"><summary>Add an editorial section</summary><?php self::sectionForm($csrf,[],$locked,$e);?></details></section><?php endif;?>
<?php if($pb&&$tab==='sponsors'):?><section class="studio-panel"><h3>Sponsor placements</h3><p>Premium sponsors receive a dedicated publication page. Shared library changes are blocked while used by any live program.</p><?php foreach($sponsors as $s):if(!$s['attachment_active'])continue;?><details class="studio-editor"><summary><strong><?=$e($s['name'])?></strong><span><?=$e(ucfirst($s['tier']))?> · order <?=(int)$s['sort_order']?></span></summary><?php if($s['logo_stored_file_id']||$s['advertisement_stored_file_id']):?><img class="studio-sponsor-thumb" src="<?=$e($url.'&preview_asset=1&kind='.($s['advertisement_stored_file_id']?'sponsor-ad':'sponsor').'&id='.(int)$s['id'])?>" alt="<?=$e($s['name'])?> artwork"><?php endif;?><form method="post" class="studio-form"><?=$csrf?><input type="hidden" name="action" value="attach_sponsor"><input type="hidden" name="sponsor_id" value="<?=(int)$s['id']?>"><fieldset <?=$locked?'disabled':''?>><?php self::placementFields($s,$e);?><button class="button">Save placement</button></fieldset></form><a href="<?=$e($url.'&tab=sponsors&sponsor='.(int)$s['id'])?>">Edit reusable sponsor</a><form method="post"><?=$csrf?><input type="hidden" name="sponsor_id" value="<?=(int)$s['id']?>"><button name="action" value="remove_sponsor" <?=$locked?'disabled':''?>>Remove from this program</button></form></details><?php endforeach;?></section>
<?php $library=PlaybillEnhancementService::sponsorLibrary($db);$editing=null;foreach($library as $s)if((int)$s['id']===(int)($_GET['sponsor']??0))$editing=$s;$placement=[];foreach($sponsors as $attached)if((int)$attached['id']===(int)($editing['id']??0))$placement=$attached;?><section class="studio-panel"><details class="studio-editor" <?=$editing?'open':''?>><summary><?=$editing?'Edit '.$e($editing['name']):'Create a sponsor'?></summary><form method="post" enctype="multipart/form-data" class="studio-form"><?=$csrf?><input type="hidden" name="action" value="save_sponsor"><input type="hidden" name="sponsor_id" value="<?=(int)($editing['id']??0)?>"><fieldset <?=$locked?'disabled':''?>><label>Sponsor name<input name="sponsor_name" maxlength="190" required value="<?=$e($editing['name']??'')?>"></label><label>Tier<select name="tier"><option value="regular">Regular</option><option value="premium" <?=($editing['tier']??'')==='premium'?'selected':''?>>Premium</option></select></label><label>Website<input type="url" name="website_url" value="<?=$e($editing['website_url']??'')?>"></label><label>Message<textarea name="public_description" maxlength="1000"><?=$e($editing['public_description']??'')?></textarea></label><label>Link label<input name="cta_label" maxlength="80" value="<?=$e($editing['cta_label']??'')?>"></label><label>Logo<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label><label>Advertisement<input type="file" name="advertisement" accept="image/jpeg,image/png,image/webp"></label><details><summary>Private library contact details</summary><?php foreach(['internal_contact_name'=>'Contact name','internal_contact_email'=>'Email','internal_contact_phone'=>'Phone','internal_notes'=>'Notes','sponsorship_starts_on'=>'Sponsorship starts','sponsorship_ends_on'=>'Sponsorship ends'] as $key=>$label):?><label><?=$label?><input name="<?=$key?>" value="<?=$e($editing[$key]??'')?>"></label><?php endforeach;?></details><?php self::placementFields($placement,$e);?><button class="button">Save sponsor &amp; placement</button></fieldset></form></details><details class="studio-editor"><summary>Add from sponsor library</summary><form method="post" class="studio-form"><?=$csrf?><input type="hidden" name="action" value="attach_sponsor"><fieldset <?=$locked?'disabled':''?>><label>Sponsor<select name="sponsor_id" required><?php foreach($library as $s):?><option value="<?=(int)$s['id']?>"><?=$e($s['name'])?></option><?php endforeach;?></select></label><?php self::placementFields([],$e);?><button class="button">Add sponsor</button></fieldset></form></details></section><?php endif;?>
<?php if($pb&&$tab==='publish'):?><section class="studio-panel"><h3>Preview the saved program</h3><p>This private preview uses the audience renderer. Unsaved fields do not appear here. Included profiles awaiting consent are preview-only; publishing checks approval separately.</p><iframe class="studio-preview" src="<?=$e($preview)?>" title="Private preview of the saved program" loading="lazy"></iframe></section><section class="studio-panel"><h3>Publication &amp; audience access</h3><p><?=$pending?> included profiles await review. Public access is a separate explicit decision from production announcements.</p><label>Permanent public URL<input data-public-url readonly value="<?=$e(PlaybillStudio::absolute($public))?>"></label><button class="button secondary" type="button" data-copy-public-url>Copy public URL</button><p data-copy-status role="status"></p><form method="post"><?=$csrf?><?php if($pb['public_enabled']):?><button class="button" name="action" value="unpublish">Unpublish program</button><?php elseif(!$closed&&$pb['editorial_status']!=='archived'):?><button class="button" name="action" value="review">Save for review</button><button class="button" name="action" value="publish">Publish program</button><?php endif;?><button name="action" value="archive">Archive program<?=$pb['public_enabled']?' · keep public':' · keep private'?></button></form><?php if($pb['public_enabled']):?><div class="studio-public-tools"><a href="<?=$e($public)?>" target="_blank" rel="noopener">Open audience program</a><a href="<?=$u('/playbill/qr?slug='.rawurlencode($pb['public_slug']).'&download=1')?>">Download QR</a><a href="<?=$u('/playbill/qr?slug='.rawurlencode($pb['public_slug']).'&background=transparent&download=1')?>">Transparent QR</a><a href="<?=$u('/playbill/sign?slug='.rawurlencode($pb['public_slug']))?>" target="_blank" rel="noopener">Print audience sign</a></div><img class="studio-qr" src="<?=$u('/playbill/qr?slug='.rawurlencode($pb['public_slug']))?>" alt="QR code to the published program"><?php else:?><p>The public URL and QR destination remain unavailable until publication. Unpublishing also blocks the public program, artwork and QR routes.</p><?php endif;?></section><?php endif;?>
<?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function sectionForm(string $csrf,array $s,bool $locked,callable $e):void
    { ?><form method="post" class="studio-form"><?=$csrf?><input type="hidden" name="action" value="save_section"><input type="hidden" name="section_id" value="<?=(int)($s['id']??0)?>"><fieldset <?=$locked?'disabled':''?>><label>Section type<select name="section_type"><?php foreach(['director_note'=>'Director’s note','welcome'=>'Welcome','acknowledgments'=>'Acknowledgments','scenes'=>'Scenes','musical_numbers'=>'Musical numbers','intermission'=>'Intermission','custom'=>'Custom'] as $value=>$label):?><option value="<?=$value?>" <?=($s['section_type']??'custom')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Heading<input name="heading" required maxlength="190" value="<?=$e($s['heading']??'')?>"></label><label>Content<textarea name="body" required maxlength="20000" rows="8"><?=$e($s['body']??'')?></textarea></label><label>Order<input name="sort_order" type="number" value="<?=(int)($s['sort_order']??10)?>"></label><button class="button" type="submit">Save section</button></fieldset></form><?php }
    private static function placementFields(array $s,callable $e):void
    { ?><label>Placement label<input name="placement_label" maxlength="100" value="<?=$e($s['placement_label']??'')?>"></label><label>Placement format<select name="placement_format"><?php foreach(['card'=>'Card','half_page'=>'Half page','full_page'=>'Full page'] as $value=>$label):?><option value="<?=$value?>" <?=($s['placement_format']??'card')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Display order<input type="number" name="sort_order" value="<?=(int)($s['sort_order']??10)?>"></label><?php }
    private static function absolute(string $path):string{return ((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').$path;}
}
